(()=>{'use strict';
 if(window.apMarketingLoaded||location.hostname!=='aptechagency.com')return;window.apMarketingLoaded=true;
 const storage='aptech-tracking-consent-v1';let consent=null,config={},loaded=false;
 try{consent=JSON.parse(localStorage.getItem(storage));}catch{}
 const page=()=>location.origin+location.pathname;
 const script=src=>{const s=document.createElement('script');s.async=true;s.src=src;document.head.append(s);};
 function event(name,meta,params={}){if(consent?.analytics&&config.ga4)window.gtag?.('event',name,params);if(consent?.marketing&&!navigator.globalPrivacyControl&&config.pixel)window.fbq?.('track',meta,params);}
 function load(){if(loaded)return;loaded=true;
  if(consent?.analytics&&/^G-[A-Z0-9]+$/.test(config.ga4||'')){window.dataLayer=window.dataLayer||[];window.gtag=function(){window.dataLayer.push(arguments);};window.gtag('js',new Date());window.gtag('config',config.ga4,{page_location:page(),page_referrer:document.referrer?new URL(document.referrer).origin:'',allow_google_signals:false,allow_ad_personalization_signals:false});script('https://www.googletagmanager.com/gtag/js?id='+config.ga4);}
  if(consent?.marketing&&!navigator.globalPrivacyControl&&/^\d+$/.test(config.pixel||'')){const q=window.fbq=function(){q.callMethod?q.callMethod.apply(q,arguments):q.queue.push(arguments);};q.queue=[];q.loaded=true;q.version='2.0';window._fbq=q;q('set','autoConfig',false,config.pixel);q('init',config.pixel);q('track','PageView',{event_source_url:page()});script('https://connect.facebook.net/en_US/fbevents.js');}
  if(location.pathname.startsWith('/services/'))event('view_service','ViewContent',{content_type:'service',content_name:location.pathname.split('/')[2]||'services'});
 }
 function choose(a,m){consent={analytics:a,marketing:m};try{localStorage.setItem(storage,JSON.stringify(consent));}catch{}document.getElementById('ap-consent')?.remove();load();}
 function preferences(){document.getElementById('ap-consent')?.remove();const box=document.createElement('section');box.id='ap-consent';box.setAttribute('aria-label','Analytics and advertising preferences');box.style.cssText='position:fixed;bottom:90px;left:16px;z-index:99999;max-width:410px;padding:20px;background:#f7f7ee;color:#243222;border:1px solid #84955f;border-radius:14px;box-shadow:0 10px 40px #0003;font:14px/1.5 system-ui';box.innerHTML='<strong>Make your privacy choice</strong><p>Allow anonymous site measurement and Meta advertising measurement? We exclude form contents, email addresses and chat messages.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button data-choice="all">Accept all</button><button data-choice="analytics">Analytics only</button><button data-choice="none">Decline</button></div><a href="/privacy/">Privacy policy</a>';box.querySelectorAll('button').forEach(b=>{b.style.cssText='padding:9px 12px;border:1px solid #84955f;border-radius:7px;background:#fff;color:#243222;cursor:pointer';b.onclick=()=>{const v=b.dataset.choice;if(loaded){try{localStorage.setItem(storage,JSON.stringify({analytics:v!=='none',marketing:v==='all'}));}catch{}location.reload();}else choose(v!=='none',v==='all');};});document.body.append(box);}
 document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;const h=a.getAttribute('href')||'';if(h.startsWith('https://wa.me/')||h.startsWith('mailto:')||h.startsWith('tel:'))event('contact_click','Contact',{contact_method:h.startsWith('mailto:')?'email':h.startsWith('tel:')?'phone':'whatsapp'});});
 document.addEventListener('aptech:brief-ready',()=>{if(consent?.analytics&&config.ga4)window.gtag?.('event','project_brief_ready');});
 document.addEventListener('aptech:lead-created',()=>event('generate_lead','Lead',{content_name:'project_enquiry'}));
 fetch('https://manage.aptechagency.com/api/marketing-config',{credentials:'omit'}).then(r=>r.ok?r.json():{}).then(c=>{config=c;if(!c.ga4&&!c.pixel)return;const button=document.createElement('button');button.textContent='Privacy choices';button.style.cssText='position:fixed;bottom:8px;left:16px;z-index:1000;font:11px system-ui;padding:5px 8px;border-radius:6px;border:1px solid #84955f;background:#f7f7ee;color:#243222';button.onclick=preferences;document.body.append(button);if(consent)load();else preferences();}).catch(()=>{});
})();
